var checkRecord = function(n) {
    const MOD = 1000000007n;
    let dp = Array.from({ length: 2 }, () => Array(3).fill(0n));
    dp[0][0] = 1n;

    for (let step = 0; step < n; step++) {
        const nextDp = Array.from({ length: 2 }, () => Array(3).fill(0n));
        for (let a = 0; a < 2; a++) {
            for (let l = 0; l < 3; l++) {
                const val = dp[a][l];
                if (val === 0n) continue;
                nextDp[a][0] = (nextDp[a][0] + val) % MOD;
                if (a === 0) {
                    nextDp[1][0] = (nextDp[1][0] + val) % MOD;
                }
                if (l < 2) {
                    nextDp[a][l + 1] = (nextDp[a][l + 1] + val) % MOD;
                }
            }
        }
        dp = nextDp;
    }

    let ans = 0n;
    for (let a = 0; a < 2; a++) {
        for (let l = 0; l < 3; l++) {
            ans = (ans + dp[a][l]) % MOD;
        }
    }
    return Number(ans);
};
